MATCH (head:ProcessInstrumentationFunction {loop_tag: 'PI-457007'}), (equipment:Equipment)-[:measured_by]->(sensor:PlantItem)
WHERE EXISTS { (sensor)-[:send_signal_to*0..]->(head) }
RETURN DISTINCT equipment.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'BV-371003'})-[:is_located_in]->(u:PlantSection)
RETURN u.unit_id AS unit_id
ORDER BY unit_id;

MATCH (:PlantItem {tag: 'P-40102'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (v:Valve)
WHERE EXISTS {
  MATCH (v)-[:line_to*1..]->(:PlantItem {tag: 'V-40001'})
}
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (head:PlantItem:ProcessInstrumentationFunction {loop_tag: 'LSHH-492004'})-[:send_signal_to*1..]->(actuator:PlantItem)-[:control]->(v:PlantItem:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (g:PlantItem:GlobeCheckValve {unit_id: '62'})
RETURN g.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'YV-550006'}), (b:PlantItem {tag: 'TK-55003'})
MATCH p = shortestPath((a)-[:line_to*]->(b))
RETURN [n IN nodes(p) WHERE n:Equipment OR n:Valve | n.tag] AS tags vel}

MATCH (a:PlantItem {tag: 'V-48802'}), (b:PlantItem {tag: 'P-48801'})
RETURN a.tag AS tag1, b.tag AS tag2, a.unit_id = b.unit_id AS same_unit
)

MATCH (item:PlantItem {tag: 'P-36502'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'P-26501C'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(s:PlantItem)-[:send_signal_to*1..]->(f:ProcessInstrumentationFunction {loop_tag: 'LIC-14052'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (loop:ProcessInstrumentationFunction {loop_tag: 'LIC-546001'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;
